//
// Integration: HMAC-authenticated TCP serving. Loopback only, CI-safe, no
// mDNS involved. Three postures against a keyed savannahd:
//   right key  -> full ask/info round-trip works
//   wrong key  -> rejected at the handshake (tag mismatch)
//   no key     -> rejected before any dispatcher runs
//
// Requires cwd = build dir with ./savannahd, ./fake-claude, cfg_secure.toml,
// test.key, and test_wrong.key (all generated by CMake).

#include <song/song.hpp>

#include <cstdio>
#include <exception>
#include <string>

#include "savannah.hpp"
#include "test_support.hpp"
#include "config.hpp"

namespace sw = song::savannah;
namespace st = savannah::test;
using song::ServiceConnection;

namespace {

// Connect with an optional HMAC key; empty key = plaintext client.
ServiceConnection connect(song::u16 port, const std::string& key) {
    return st::connect_tcp("127.0.0.1", port, key);
}

// One ask that must finish clean; returns its text.
std::string ask_text(ServiceConnection& conn, const std::string& prompt) {
    auto r = st::ask(conn, prompt);
    CHECK(r.ok());
    return r.text;
}

}  // namespace

int main() {
    const std::string key = savannah::load_hmac_key("test.key");
    const std::string wrong_key = savannah::load_hmac_key("test_wrong.key");

    auto d = st::Daemon::spawn("cfg_secure.toml");
    CHECK(d.pid > 0);
    CHECK(d.port != 0);
    if (st::g_failures) return 1;

    // ---- right key: everything works over the secured transport ----
    {
        auto conn = connect(d.port, key);
        CHECK(ask_text(conn, "over hmac") == "over hmac");

        auto info = sw::AgentNodeProxy(conn).info();
        CHECK(info.name == "secure-node");
    }

    // ---- wrong key: the server's init confirmation fails verification
    //      client-side; nothing usable comes back ----
    {
        bool rejected = false;
        try {
            auto conn = connect(d.port, wrong_key);
            sw::AgentNodeProxy(conn).status();
        } catch (const std::exception&) {
            rejected = true;
        }
        CHECK(rejected);
    }

    // ---- no key: the server drops the client on its first unauthenticated
    //      message, before any dispatcher runs ----
    {
        bool rejected = false;
        try {
            auto conn = connect(d.port, "");
            sw::AgentNodeProxy(conn).status();
        } catch (const std::exception&) {
            rejected = true;
        }
        CHECK(rejected);
    }

    // ---- and the node is still healthy for keyed clients afterward ----
    {
        auto conn = connect(d.port, key);
        CHECK(ask_text(conn, "still alive") == "still alive");
    }

    return st::finish("test_secure");
}
